css='''
*{box-sizing:border-box}body{margin:0;color:#F7F4F0;font:15px "Pretendard Variable",Pretendard,"Noto Sans KR",-apple-system,"Apple SD Gothic Neo",system-ui,sans-serif;background:#12081c}button,input,select{font:inherit;color:inherit}button{cursor:pointer}button:disabled{cursor:default}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #D2AEFC;outline-offset:2px}button{border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.1);border-radius:16px;min-height:44px}header{height:56px;display:grid;grid-template-columns:96px 1fr 96px;align-items:center;padding:0 16px}header b{text-align:center}header button{width:44px;border-radius:50%;font-size:24px}.save{font-size:12px;text-align:right;color:#CFC6D6}.steps{height:24px;display:flex;gap:8px;justify-content:center;align-items:center}.steps i{width:8px;height:8px;border-radius:8px;background:#ffffff55}.steps i:first-child{background:#B373EF}.steps i:nth-child(2){width:24px;background:#fff}main{height:calc(100dvh - 160px);padding:16px;display:flex;align-items:center;justify-content:center;overflow:auto}.card{width:640px;max-width:100%;border:1px solid rgba(255,255,255,.14);border-radius:24px;background:rgba(24,12,36,.78);padding:24px;display:flex;flex-direction:column;gap:16px;flex-shrink:0}h1{font-size:24px;line-height:1.3;text-align:center;margin:0;font-weight:800}.segments{display:flex;flex-wrap:wrap;gap:8px}.segments button{flex:1 1 128px;min-height:52px;font-size:15px;font-weight:600}.on{background:#5F0080;border-color:#B373EF}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.group{min-width:0;display:flex;flex-direction:column;gap:8px}.label{font-size:13px;font-weight:600;color:#CFC6D6;line-height:20px}.control{height:56px;min-height:56px;width:100%;border-radius:16px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.08);font-size:15px;font-weight:700}.field{display:flex;justify-content:center;align-items:center;gap:8px;padding:0 12px;white-space:nowrap}.field[aria-expanded=true]{border-color:#B373EF}.stepper{display:grid;grid-template-columns:44px 1fr 44px;align-items:center;gap:8px;padding:0 8px}.stepper button{border:0;background:#ffffff19;width:44px;height:44px;border-radius:50%;font-size:24px}.stepper b{text-align:center;white-space:nowrap}.span2{grid-column:span 2}.reminders{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.reminders button{height:56px;font-size:13px;font-weight:600;padding:0 4px}.days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr))}.days button{height:48px;border:0;background:none;display:grid;place-items:center;padding:0}.days span{width:40px;height:40px;display:grid;place-items:center;background:#ffffff19;border:1px solid #ffffff24;border-radius:50%;font-size:13px}.days [aria-pressed=true] span{background:#5F0080;border-color:#B373EF}.note{border:0;background:transparent;display:flex;align-items:center;gap:10px;text-align:left;font-size:12px;line-height:1.6;color:#CFC6D6;padding:0}.note .edit{margin-left:auto;font-size:24px}.note .icon{font-size:22px}footer{height:80px;padding:16px;display:flex;justify-content:center;gap:8px}footer button{height:48px;border-radius:999px;font-weight:700}footer .prev{width:211px}footer .next{width:421px;background:#5F0080;border-color:transparent}.popup{position:fixed;z-index:30;width:326px;padding:8px;border-radius:16px;background:#24132f;border:1px solid #B373EF;box-shadow:0 16px 48px #0008;display:flex;flex-direction:column;gap:8px;max-height:calc(100dvh - 16px);overflow-y:auto}.popup[hidden],.backdrop[hidden]{display:none}.pophead{display:grid;grid-template-columns:44px 1fr 44px;align-items:center;text-align:center;min-height:44px}.pophead b{font-size:15px}.pophead button{border-radius:12px;background:transparent;font-size:24px}.week,.dates{display:grid;grid-template-columns:repeat(7,minmax(0,1fr))}.week span{text-align:center;color:#CFC6D6;font-size:13px;line-height:28px}.date{height:44px;min-width:44px;border-radius:10px;background:transparent;border:1px solid transparent;padding:0;font-size:18px;font-weight:600;position:relative}.date:disabled{opacity:.35}.date[aria-selected=true]{background:#5F0080;border-color:#5F0080}.date[aria-current=date]:after{content:"";position:absolute;bottom:3px;left:calc(50% - 2px);width:4px;height:4px;background:#D2AEFC;border-radius:50%}.date:focus-visible{outline-offset:-3px}.legend{font-size:12px;color:#CFC6D6;padding:0 4px}.legend:before{content:"●";color:#D2AEFC;padding-right:5px}.sheethead{display:none}.chips{display:grid;grid-template-columns:1fr 1fr 2fr;gap:4px}.chips button{font-size:12px;border-radius:12px;background:rgba(210,174,252,.14);padding:0 4px}.backdrop{position:fixed;inset:0;z-index:29;background:#12081c77}.native{display:none}.timepop{width:186px}.time-tabs,.time-cols{display:grid;grid-template-columns:1fr 1fr;gap:8px}.time-tabs button{border-radius:12px;font-size:15px;background:transparent}.time-tabs button.active{background:rgba(210,174,252,.14);border-color:#D2AEFC}.time-list{display:flex;flex-direction:column;gap:2px;max-height:220px;overflow:auto;border-radius:12px;background:#ffffff0a}.time-list button{flex:none;width:100%;font-size:18px;font-weight:600;border:0;border-radius:10px;background:transparent}.time-list .on{background:#5F0080}.mobile-time{display:none}
@media(max-width:767px){.card{padding:16px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.span2{grid-column:1/-1}.stepper{gap:0;padding:0}.days span{width:36px;height:36px}.popup.calendar{width:100%;left:0!important;top:auto!important;bottom:0;border-radius:24px 24px 0 0;padding:16px 16px calc(16px + env(safe-area-inset-bottom,0px));max-height:calc(100dvh - 16px)}.sheethead{display:flex;align-items:center;justify-content:space-between;min-height:44px}.sheethead button{min-width:60px;background:transparent}.sheethead b{font-size:18px}.date{height:44px}.chips button{font-size:13px}.desktop-time{display:none}.mobile-time{display:grid;grid-template-columns:1fr 1fr;gap:8px}.mobile-time select{min-width:0;padding:0 8px}.mobile-time option{background:#24132f}.d3 .native{display:block;position:absolute;inset:0;width:100%;height:56px;opacity:0;cursor:pointer;color-scheme:dark}.d3 .date-wrap{position:relative}.d3 #date-trigger{pointer-events:none}footer .prev{width:118px}footer .next{width:232px}.reminders button{height:52px}}
@media(max-height:640px){main{align-items:flex-start}.card{padding:16px}footer{height:72px;padding-top:8px}main{height:calc(100dvh - 152px)}}
'''
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>클래스 만들기</title><style>CSS</style><body class="dN"><header><button aria-label="나가기">×</button><b>클래스 만들기</b><span class="save">♧ 초안 저장</span></header><div class="steps"><i></i><i></i><i></i><i></i></div><main><section class="card"><h1>언제 진행할까요?</h1><div class="segments"><button>바로 지금</button><button class="on">☷ 정해진 횟수</button><button>⇄ 계속 이어져요</button></div><div class="grid"><div class="group first date-group"><span class="label">시작 날짜</span><div class="date-wrap"><button id="date-trigger" class="control field" aria-haspopup="dialog" aria-expanded="false" aria-controls="calendar">11/3(화) ﹀</button><input class="native" aria-label="시작 날짜" type="date" min="2026-11-03" value="2026-11-03"></div></div><div class="group first time-group"><span class="label">시작 시각 · 5분</span><button id="time-trigger" class="control field desktop-time" aria-haspopup="dialog" aria-expanded="false">오전 10:00 ﹀</button><div class="mobile-time"><select class="control" aria-label="시작 시각 시"><option>오전 10시</option><option>오전 11시</option></select><select class="control" aria-label="시작 시각 분"><option>00분</option><option>05분</option></select></div></div><div class="group first duration-group"><span class="label">소요 시간</span><div class="control stepper"><button aria-label="소요 시간 줄이기">−</button><b>70 분</b><button aria-label="소요 시간 늘리기">＋</button></div></div><div class="group"><span class="label">횟수</span><div class="control stepper"><button aria-label="횟수 줄이기">−</button><b>8 회</b><button aria-label="횟수 늘리기">＋</button></div></div><div class="group span2"><span class="label">예약 알림</span><div class="reminders"><button>끄기</button><button class="on">하루 전</button><button>1시간 전</button><button>둘 다</button></div></div></div><div class="group"><span class="label">요일</span><div class="days">DAYS</div></div><button class="note"><span class="icon">▧</span><span>건너뛸 날짜·반복 간격 설정 · 공휴일은 자동으로 건너뛰지 않아요</span><span class="edit">♢</span></button></section></main><footer><button class="prev">‹　이전</button><button class="next">다음　›</button></footer><div class="backdrop" hidden></div><section class="popup calendar" id="calendar" role="dialog" aria-label="시작 날짜 선택" aria-modal="false" hidden><div class="sheethead"><b>시작 날짜</b><button id="close">닫기</button></div>CHIPS<div class="pophead"><button id="prev" aria-label="이전 달">‹</button><b id="month" aria-live="polite"></b><button id="next" aria-label="다음 달">›</button></div><div class="week" aria-hidden="true">WEEK</div><div class="dates" role="grid" aria-label="날짜"></div><span class="legend">오늘</span></section><section class="popup timepop" id="timepop" role="dialog" aria-label="시작 시각 선택" hidden><div class="time-tabs"><button class="active">오전</button><button>오후</button></div><div class="time-cols"><div class="time-list">HOURS</div><div class="time-list">MINUTES</div></div></section><script>JS</script></body></html>'''
js='''
const today='2026-11-03',variant=N;let value=today,month=new Date('2026-11-01T12:00:00Z'),cursor=today;
const $=s=>document.querySelector(s),pop=$('#calendar'),trigger=$('#date-trigger'),shade=$('.backdrop'),tp=$('#timepop');
const iso=d=>d.toISOString().slice(0,10),parse=s=>new Date(s+'T12:00:00Z');
function moveDate(s,n){const d=parse(s);d.setUTCDate(d.getUTCDate()+n);return iso(d)}
function label(s){const d=parse(s);return `${d.getUTCMonth()+1}/${d.getUTCDate()}(${'일월화수목금토'[d.getUTCDay()]})`}
function position(p,t){const r=t.getBoundingClientRect(),w=p.getBoundingClientRect().width,h=p.getBoundingClientRect().height;p.style.left=Math.max(8,Math.min(r.left,innerWidth-w-8))+'px';p.style.top=Math.max(8,Math.min(r.bottom+8,innerHeight-h-8))+'px'}
function render(focus=false){$('#month').textContent=`${month.getUTCFullYear()}년 ${month.getUTCMonth()+1}월`;$('#prev').disabled=iso(month)<='2026-11-01';let cells='';for(let i=0;i<month.getUTCDay();i++)cells+='<span></span>';const end=new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth()+1,0)).getUTCDate();for(let n=1;n<=end;n++){let d=new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth(),n,12)),s=iso(d);cells+=`<button class="date" role="gridcell" data-date="${s}" aria-label="${s}${s===today?' 오늘':''}" aria-selected="${s===value}" ${s===today?'aria-current="date"':''} ${s<today?'disabled':''} tabindex="${s===cursor?0:-1}">${n}</button>`}$('.dates').innerHTML=cells;const children=[...$('.dates').children];for(let i=0;i<children.length;i+=7){const row=document.createElement('div');row.setAttribute('role','row');row.style.display='contents';children.slice(i,i+7).forEach(c=>row.appendChild(c));$('.dates').appendChild(row)}pop.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>pick(b.dataset.date));if(!pop.hidden&&innerWidth>=768)position(pop,trigger);if(focus)pop.querySelector(`[data-date="${cursor}"]`)?.focus({preventScroll:true})}
function close(returnFocus=true){pop.hidden=true;shade.hidden=true;trigger.setAttribute('aria-expanded','false');if(returnFocus)(variant===3&&innerWidth<768?$('.native'):trigger).focus({preventScroll:true})}
function pick(s){if(s<today)return;value=s;document.body.dataset.date=value;trigger.textContent=label(value)+' ﹀';$('.native').value=value;close()}
function open(){tp.hidden=true;$('#time-trigger').setAttribute('aria-expanded','false');pop.hidden=false;cursor=value;month=parse(value.slice(0,7)+'-01');trigger.setAttribute('aria-expanded','true');shade.hidden=innerWidth>=768;pop.setAttribute('aria-modal',innerWidth<768?'true':'false');render(true)}
trigger.onclick=()=>pop.hidden?open():close();$('#close').onclick=()=>close();shade.onclick=()=>close();
function changeMonth(delta,focus=false){const day=parse(cursor).getUTCDate();month=new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth()+delta,1,12));if(iso(month)<'2026-11-01')month=parse('2026-11-01');let end=new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth()+1,0)).getUTCDate();cursor=iso(new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth(),Math.min(day,end),12)));if(cursor<today)cursor=today;render(focus)}
$('#prev').onclick=()=>changeMonth(-1);$('#next').onclick=()=>changeMonth(1);
pop.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close();return}let delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[e.key];if(delta&&e.target.dataset.date){e.preventDefault();cursor=moveDate(e.target.dataset.date,delta);if(cursor<today)cursor=today;month=parse(cursor.slice(0,7)+'-01');render(true)}if(e.key==='PageUp'||e.key==='PageDown'){e.preventDefault();changeMonth(e.key==='PageUp'?-1:1,true)}if(e.key==='Tab'){let items=[...pop.querySelectorAll('button:not(:disabled)')].filter(e=>e.getBoundingClientRect().width&&e.tabIndex>=0),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};
$('.native').onchange=e=>{if(e.target.value>=today)pick(e.target.value);else e.target.value=value};
$('.chips')?.querySelectorAll('button').forEach((b,i)=>b.onclick=()=>pick(moveDate(today,[0,1,7][i])));
document.addEventListener('pointerdown',e=>{if(!pop.hidden&&!pop.contains(e.target)&&!trigger.contains(e.target)&&e.target!==shade)close(false);if(!tp.hidden&&!tp.contains(e.target)&&!$('#time-trigger').contains(e.target)){tp.hidden=true;$('#time-trigger').setAttribute('aria-expanded','false')}});
$('#time-trigger').onclick=()=>{close(false);tp.hidden=!tp.hidden;$('#time-trigger').setAttribute('aria-expanded',String(!tp.hidden));if(!tp.hidden)position(tp,$('#time-trigger'))};tp.querySelectorAll('.time-list button').forEach(b=>b.onclick=()=>{b.parentElement.querySelector('.on')?.classList.remove('on');b.classList.add('on');if(b.parentElement===tp.querySelectorAll('.time-list')[1]){tp.hidden=true;$('#time-trigger').setAttribute('aria-expanded','false');$('#time-trigger').focus()}});tp.onkeydown=e=>{if(e.key==='Escape'){tp.hidden=true;$('#time-trigger').setAttribute('aria-expanded','false');$('#time-trigger').focus()}};
function nativeA11y(){const native=variant===3&&innerWidth<768;trigger.tabIndex=native?-1:0;trigger.setAttribute('aria-hidden',String(native));$('.native').disabled=!native}nativeA11y();window.addEventListener('resize',()=>{nativeA11y();if(!pop.hidden){shade.hidden=innerWidth>=768;render()}if(!tp.hidden)position(tp,$('#time-trigger'))});render();document.body.dataset.date=value;
if(new URLSearchParams(location.search).has('open')&&!(variant===3&&innerWidth<768))open();
'''
for n in (1,2,3):
    s=html.replace('dN',f'd{n}').replace('DAYS',''.join(f'<button aria-label="{d}요일" aria-pressed="{str(d=="화").lower()}"><span>{d}</span></button>' for d in '월화수목금토일')).replace('CHIPS','<div class="chips"><button>오늘</button><button>내일</button><button>다음 주 같은 요일</button></div>' if n==2 else '').replace('WEEK',''.join(f'<span>{d}</span>' for d in '일월화수목금토')).replace('HOURS',''.join(f'<button class="{"on" if h==10 else ""}">{h}시</button>' for h in range(7,13))).replace('MINUTES',''.join(f'<button class="{"on" if m==0 else ""}">{m:02}분</button>' for m in range(0,60,5))).replace('JS',js.replace('variant=N',f'variant={n}'))
    s=s.replace('CSS',css+f'body{{background:linear-gradient(to bottom,rgba(18,8,28,.35),rgba(18,8,28,.72)),url(data:image/webp;base64,{bg}) center/cover fixed}}')
    (out/f'option-d{n}.html').write_text(s)
